// Generated from sw5e_source/class.json & classImprovement.json (100% verbatim-verified)
const SW5E_CLASS_POOL_META = {"Berserker":{"poolName":"Berserker Instincts","tabLabel":"Instincts","marker":"### Berserker Instincts","levelCol":"Berserker Instincts"},"Consular":{"poolName":"Force-Empowered Castings","tabLabel":"Force-Empowered","marker":"### Force-Empowered Castings","levelCol":"Force-Empowered Casting Options"},"Engineer":{"poolName":"Engineer Improvements","tabLabel":"Class Improvement","marker":"","levelCol":""},"Fighter":{"poolName":"Fighter Strategies","tabLabel":"Strategies","marker":"### Fighter Strategies","levelCol":"Strategies Known"},"Guardian":{"poolName":"Guardian Auras","tabLabel":"Auras","marker":"### Guardian Auras","levelCol":"Auras Known"},"Monk":{"poolName":"Monastic Vows","tabLabel":"Vows","marker":"### Monastic Vows","levelCol":"Monastic Vows"},"Operative":{"poolName":"Operative Exploits","tabLabel":"Exploits","marker":"### Operative Exploits","levelCol":"Operative Exploits"},"Scholar":{"poolName":"Discoveries","tabLabel":"Discoveries","marker":"### Discoveries","levelCol":"Discoveries"},"Scout":{"poolName":"Scout Routines","tabLabel":"Routines","marker":"### Scout Routines","levelCol":"Routines Known"},"Sentinel":{"poolName":"Sentinel Ideals","tabLabel":"Ideals","marker":"### Sentinel Ideals","levelCol":"Ideals Known"}};
const SW5E_CLASS_OPTIONS = [{"name": "Acklay's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "While raging, you have advantage on Constitution saving throws.", "mechanics": {"rageConSaveAdv": true}, "summary": "While raging, advantage on Constitution saving throws."}, {"name": "Bantha's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "7th level", "description": "Your carrying capacity and the weight you can push, drag, or lift doubles. If it would already double, it instead triples. Additionally, you have advantage on Strength checks made to push, pull, lift, or break objects.", "mechanics": {"carryingDouble": true}, "summary": "Double carrying, push, drag, and lift capacity (triple if already doubled); advantage on Strength checks to push, pull, lift, or break objects."}, {"name": "Blurrg's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "Whether mounted or on foot, your travel pace is doubled, as is the travel pace of up to ten companions while they're within 60 feet of you and you're not incapacitated.", "summary": "Double travel pace for you and up to 10 companions within 60 ft while conscious."}, {"name": "Boggdo's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "13th level", "description": "While raging you have a flying speed equal to your current walking speed, though you fall if you end your turn in the air and nothing else is holding you aloft.", "mechanics": {"rageFlySpeed": "walk"}, "summary": "While raging, flying speed equal to walking speed (fall if you end your turn unsupported in the air)."}, {"name": "Chirodactyl's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "7th level", "description": "While raging, you have blindsight to a range of 30 feet, and you have advantage on Wisdom (Perception) checks that rely on sound, as long as you aren't deafened.", "mechanics": {"rageBlindsight": 30}, "summary": "While raging, 30 ft blindsight and advantage on hearing-based Perception checks."}, {"name": "Dewback's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "Choose three damage types other than true damage. While raging, you have resistance to the chosen damage types.", "mechanics": {"rageExtraResistances": true}, "summary": "Choose three damage types (excluding true); gain resistance to them while raging."}, {"name": "Fighter's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "You adopt a particular style of fighting as your specialty. Choose one of the Fighting Style options, detailed in Chapter 6.", "mechanics": {"grantsFightingStyle": true}, "summary": "Learn one Fighting Style option."}, {"name": "Fyrnock's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "While raging, you can use your bonus action to leap up to 30 feet to an empty space you can see. When you land you deal kinetic damage equal to your Strength modifier to each creature within 5 feet of where you land. You can use this feature twice. You gain an additional use at 5th, 9th, 13th, and 17th level. You regain all expended uses when you complete a long rest.", "mechanics": {"rageBonusLeap": true}, "summary": "While raging, bonus action leap up to 30 ft, dealing Strength modifier kinetic damage to creatures within 5 ft on landing."}, {"name": "Hawk's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "7th level", "description": "You can see up to 1 mile away with no difficulty. You are able to discern even fine details as though looking at something no more than 100 feet away from you. Additionally, dim light doesn't impose disadvantage on your Wisdom (Perception) checks.", "summary": "See clearly up to 1 mile away (fine detail as at 100 ft); dim light does not impose disadvantage on Perception."}, {"name": "Katarn's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "You gain a climbing speed equal to your movement speed.", "mechanics": {"climbSpeed": "walk"}, "summary": "Climbing speed equal to your movement speed."}, {"name": "Loth-cat's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "While you're raging, other creatures have disadvantage on opportunity attack rolls against you, and you can take the Dash action as a bonus action on your turn.", "mechanics": {"rageBonusDash": true, "rageOADisadv": true}, "summary": "While raging, opportunity attacks against you have disadvantage and you can Dash as a bonus action."}, {"name": "Predator's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "Your speed increases by 10 feet.", "mechanics": {"speedBonus": 10}, "summary": "Walking speed increases by 10 feet."}, {"name": "Rancor's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "13th level", "description": "While you're raging any creature within 5 feet of you that's hostile to you has disadvantage on attack rolls against targets other than you or another character with this feature. An enemy is immune to this effect if it can't see or hear you or if it can't be frightened.", "summary": "While raging, hostile creatures within 5 ft have disadvantage on attacks against targets other than you."}, {"name": "Tactician's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "", "description": "When you use your Reckless Attack feature, you can choose to not have advantage on your attack rolls this turn. If you do so, friendly creatures within 5 feet of a hostile creature that is within 5 feet of you have advantage on attack rolls against that creature.", "summary": "Forgo Reckless Attack advantage to grant allies within 5 ft advantage against hostile creatures within 5 ft of you."}, {"name": "Tracker's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "7th level", "description": "You can track other creatures while traveling at a fast pace, and you can move stealthily while traveling at a normal pace.", "summary": "Track creatures at a fast travel pace and move stealthily at a normal travel pace."}, {"name": "Terentatek's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "13th level", "description": "When you are forced to make a saving throw against a force power, you can immediately use your reaction to move up to half your speed towards the source power's caster. If you end this movement within 5 feet of the target, you can immediately make one melee weapon attack against the target as a part of that reaction.", "summary": "Reaction when forced to save against a force power: move up to half speed toward the caster and make a melee weapon attack if within 5 ft."}, {"name": "Varactyl's Instinct", "className": "Berserker", "poolName": "Berserker Instincts", "prerequisite": "13th level", "description": "While raging, you have advantage on Dexterity checks, your attack rolls can't suffer from disadvantage, and each slowed level only reduces your speed by 5 feet, unless it would reduce your speed to 0.", "mechanics": {"rageDexCheckAdv": true, "rageSlowedStep": 5}, "summary": "While raging, advantage on Dexterity checks, attacks cannot have disadvantage, and slowed levels reduce speed by only 5 ft."}, {"name": "Careful Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that forces other creatures to make a saving throw, you can protect some of those creatures from the power's full force. To do so, you spend 1 additional force point and choose a number of those creatures up to your Wisdom or Charisma modifier (your choice, minimum of one). A chosen creature automatically succeeds on its saving throw against the power.", "summary": "Spend +1 Force point to let up to Wisdom or Charisma modifier creatures automatically succeed on the power's save."}, {"name": "Distant Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that has a range of 5 feet or greater, you can spend 1 additional force point to double the range of the power.\n\nAlternatively, when you cast a power that has a range of touch, you can spend 1 additional force point to make the range of the power 30 feet.", "summary": "Spend +1 Force point to double a power's range (or increase Touch range to 30 ft)."}, {"name": "Extended Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that has a duration of 1 minute or longer, you can spend 1 additional force point to double its duration, to a maximum duration of 24 hours.", "summary": "Spend +1 Force point to double a power's duration (up to 24 hours) if 1 minute or longer."}, {"name": "Heightened Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that forces a creature to make a saving throw to resist its effects, you can spend 3 additional force points to give one target of the power disadvantage on its first saving throw made against the power.", "summary": "Spend +3 Force points to give one target disadvantage on its first saving throw against the power."}, {"name": "Improved Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you roll damage for a power, you can spend 1 additional force point to reroll a number of the damage dice up to your Wisdom or Charisma modifier (your choice, minimum of one). You must use the new rolls.\n\nYou can use Improved Power even if you have already used a different Force-Empowered Casting option during the casting of the power.", "summary": "Spend +1 Force point to reroll up to Wisdom or Charisma modifier damage dice for a power."}, {"name": "Lingering Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that requires concentration to maintain you can choose to spend 3 additional force points. If you do, when you lose concentration on the power, the power will not end until the end of your next turn.", "summary": "Spend +3 Force points so a concentration power persists until the end of your next turn if you lose concentration."}, {"name": "Pinpoint Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that allows you to force creatures in an area to make a saving throw you can instead spend 1 force point and make a ranged force attack against a single target that would be in the range. On a hit the target suffers the effects as though they failed their saving throw.", "summary": "Spend +1 Force point to turn an area saving-throw power into a ranged force attack against one target."}, {"name": "Quickened Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that has a casting time of 1 action, you can spend 2 additional force points to change the casting time to 1 bonus action for this casting.", "summary": "Spend +2 Force points to cast an Action power as a Bonus Action."}, {"name": "Refocused Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you are forced to make a Constitution saving throw to maintain concentration on a power you can use your reaction and spend 2 force points to automatically succeed on the saving throw.\n\nYou can use Refocused Power even if you have already used a different Force-Empowered Casting option during the casting of the power.", "summary": "Reaction + 2 Force points to automatically succeed on a Constitution concentration save."}, {"name": "Seeking Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "If you miss with a force power that calls for an attack roll, you can spend 2 force points to reroll the attack. You must use the new roll.\n\nYou can use Seeking Power even if you have already used a different Force-Empowered Casting option during the casting of the power.", "summary": "Spend 2 Force points to reroll a missed force power attack roll."}, {"name": "Twinned Power", "className": "Consular", "poolName": "Force-Empowered Castings", "prerequisite": "", "description": "When you cast a power that can only have one target and doesn't have a range of self, you can spend a number of additional force points equal to the power's level to choose a second target in range with the same power (1 force point if the power is at-will).", "summary": "Spend Force points equal to power level (1 for at-will) to target a second creature with a single-target power."}, {"name": "Cover Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "You treat partial cover as one step higher (from one-quarter to half or half to three-quarters). While in cover, your attacks reduce partial cover by one step (from three-quarters to half or half to one-quarter).", "mechanics": {"coverStepUp": true}, "summary": "Treat partial cover as one step higher; while in cover, your attacks reduce targets' partial cover by one step."}, {"name": "Cunning Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "Choose two from the following. You can perform each of the chosen options with your bonus action, instead of your action: \n- Applying poison\n- Dash\n- Disengage\n- Guard\n- Help\n- Hide\n- Search\n- Throwing grenades and setting mines\n- While mounted on a controlled beast, having your beast make a single melee attack against a creature within its reach\n- While mounted on a vehicle, taking a vehicle action (you can't take the same action twice in one turn)", "summary": "Choose two utility actions (Dash, Disengage, Guard, Help, Hide, Search, Poison, Grenades/Mines, Mount/Vehicle) to use as a bonus action."}, {"name": "Enduring Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "You only need 3 hours of sleep during a long rest to gain its benefits, instead of 6. Additionally, if your long rest would be interrupted, you only need to complete the long rest instead of restarting it to gain its benefits. Lastly, you have advantage on saving throws against exhaustion.", "summary": "Only 3 hours of sleep needed for a long rest, interruptions do not reset rest, and advantage on saves against exhaustion."}, {"name": "Mastery Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "You've mastered a particular style of fighting. Choose one of the Fighting Mastery options, detailed in Chapter 6.", "mechanics": {"grantsFightingMastery": true}, "summary": "Learn one Fighting Mastery option."}, {"name": "Lightweapon Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "You gain proficiency in all lightweapons. Additionally, you no longer need the ability to cast force powers to learn features that grant lightsaber forms, and you learn one lightsaber form of your choice.", "mechanics": {"weaponProfCategory": "Lightweapon", "unlocksLightsaberForms": true}, "summary": "Proficiency in all lightweapons; learn one Lightsaber Form without needing forcecasting."}, {"name": "Maneuver Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "You learn two additional maneuvers. When you complete a short rest, you can replace one of these maneuvers with another one. When you complete a long rest, you can replace both of these maneuvers with other ones.", "summary": "Learn two additional maneuvers; swap one on a short rest or both on a long rest."}, {"name": "Skilled Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "You gain proficiency in a skill and a tool, or two tools.", "summary": "Gain proficiency in one skill and one tool, or two tools."}, {"name": "Style Strategist", "className": "Fighter", "poolName": "Fighter Strategies", "prerequisite": "", "description": "You adopt a second fighting style. Choose one of the fighting style options, detailed in Chapter 6. When you complete a long rest, you can change this style out for another one.", "mechanics": {"grantsFightingStyle": true}, "summary": "Learn a second Fighting Style; swap it out after a long rest."}, {"name": "Aura of Conquest", "className": "Guardian", "poolName": "Guardian Auras", "prerequisite": "", "description": "Whenever a creature who is frightened of you starts its turn within 5 feet of you, its gains 4 slowed levels and takes psychic damage equal to half your guardian level.", "mechanics": {"auraEffect": "Aura of Conquest"}, "summary": "Frightened creatures starting their turn within your aura gain 4 slowed levels and take psychic damage equal to half your Guardian level."}, {"name": "Aura of Conviction", "className": "Guardian", "poolName": "Guardian Auras", "prerequisite": "", "description": "You and friendly creatures within 5 feet of you have advantage on saving throws against effects that would cause you to be charmed or frightened.", "mechanics": {"auraEffect": "Aura of Conviction", "charmFrightSaveAdv": true}, "summary": "You and allies within your aura have advantage on saves against being charmed or frightened."}, {"name": "Aura of Hatred", "className": "Guardian", "poolName": "Guardian Auras", "prerequisite": "", "description": "You and friendly creatures within 5 feet of you gain a bonus to the first melee weapon damage rolls you make each round equal to your Charisma modifier (minimum of +1).", "mechanics": {"auraEffect": "Aura of Hatred", "meleeFirstDmgCha": true}, "summary": "You and allies within your aura add your Charisma modifier (minimum +1) to the first melee weapon damage roll each round."}, {"name": "Aura of Presence", "className": "Guardian", "poolName": "Guardian Auras", "prerequisite": "", "description": "Whenever you or a friendly creature within 5 feet of you must make a saving throw, the creature can add your Wisdom modifier to the saving throw.", "mechanics": {"auraEffect": "Aura of Presence", "allSaveBonusWis": true}, "summary": "You and allies within your aura add your Wisdom modifier to saving throws."}, {"name": "Aura of Protection", "className": "Guardian", "poolName": "Guardian Auras", "prerequisite": "", "description": "Whenever a creature within 5 feet of you takes damage, you can use your reaction to take that damage instead of that creature taking it. This feature doesn't transfer any other effects that might accompany the damage, and this damage can't be reduced in any way.", "mechanics": {"auraEffect": "Aura of Protection"}, "summary": "Reaction when a creature within your aura takes damage to take that unreduced damage instead."}, {"name": "Aura of Vigor", "className": "Guardian", "poolName": "Guardian Auras", "prerequisite": "", "description": "Whenever a friendly creature starts its turn within 5 feet of you, that creature gains temporary hit points equal to your Wisdom or Charisma modifier (your choice, minimum of one).", "mechanics": {"auraEffect": "Aura of Vigor", "turnTempHPForce": true}, "summary": "Allies starting their turn within your aura gain temporary HP equal to your Wisdom or Charisma modifier (minimum 1)."}, {"name": "Aura of Warding", "className": "Guardian", "poolName": "Guardian Auras", "prerequisite": "", "description": "You and friendly creatures within 5 feet of you have resistance to damage from force powers.", "mechanics": {"auraEffect": "Aura of Warding", "resistForcePower": true}, "summary": "You and allies within your aura have resistance to damage from force powers."}, {"name": "Vow of Deflection", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You can use your reaction to divert a strike when you are dealt damage by a melee weapon attack. When you do so, the damage taken by the attack is reduced by 1d10 + your Dexterity modifier + your monk level.", "mechanics": {"meleeDeflectReaction": true}, "summary": "Reaction on melee weapon hit: reduce damage by 1d10 + Dexterity modifier + Monk level."}, {"name": "Vow of the Devoted", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You gain a limited ability to manipulate the Force. See chapter 10 for the general rules of forcecasting and chapter 11 for the force powers list.\n\n***Force Powers Known.*** You learn 2 force powers of your choice. You learn an additional power at 3rd, 5th, 7th, 9th, 11th, 13th, 15th, and 17th level. You may not learn a force power of a level higher than your Max Power Level, and you may learn a force power at the same time you learn its prerequisite. You may only learn universal powers in this way.\n\n***Force Points.*** Rather than force points, powers you learn through this vow are cast using your focus points, at 1 focus point per power level. You may only cast universal powers in this way.\n\n***Max Power Level.*** Many force powers can be overpowered, consuming more focus points to create a greater effect. You can overpower these abilities to a maximum level, which increases at higher levels. Your Max Power Level is 1st. It increases to 2nd at 7th level, 3rd at 13th level, and 4th at 17th level. You may only cast force powers at 4th-level once. You regain the ability to do so after a long rest.\n\n***Forcecasting Ability.*** You use your focus ability whenever a power refers to your forcecasting ability. If a power you cast with focus points calls for a saving throw, you use your focus save DC. If a power you cast with focus points calls for an attack roll, you use your focus attack modifier.", "mechanics": {"unlocksForce": true}, "summary": "Learn universal Force powers cast with Focus points (1 point per power level)."}, {"name": "Vow of Fate", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "7th level", "description": "When you finish a short or long rest, roll a d20 and record the number rolled. Once before your next short or long rest, you can replace any attack roll, saving throw, or ability check made by you or a creature within 5 feet of you with this roll. You must choose to do so before the roll.", "mechanics": {"shortRestD20Pool": true}, "summary": "After a short or long rest, roll a d20 and save it to replace one attack, save, or check within 5 ft."}, {"name": "Vow of the Fighter", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You adopt a particular style of fighting as your specialty. Choose one of the fighting Style options, detailed in Chapter 6.", "mechanics": {"grantsFightingStyle": true}, "summary": "Learn one Fighting Style option."}, {"name": "Vow of the Focused", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You can substitute Strength, Constitution, or Intelligence (chosen when you take this vow) for Wisdom or Charisma for your monk class features, except for other vows and Monastic Tradition features.", "summary": "Substitute Strength, Constitution, or Intelligence for Wisdom/Charisma in base Monk class features."}, {"name": "Vow of Fortitude", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "7th level", "description": "You can use your action or bonus action to end one effect on yourself that is causing you to be blinded or deafened.", "mechanics": {"clearBlindDeafAction": true}, "summary": "Action or bonus action to end one blinded or deafened effect on yourself."}, {"name": "Vow of Freedom", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You ignore unenhanced difficult terrain, and when you would use your action to break free of an effect that is grappling or restraining you, you can instead use your bonus action.", "mechanics": {"ignoreDifficultTerrain": true}, "summary": "Ignore unenhanced difficult terrain; escape grapples or restraints as a bonus action."}, {"name": "Vow of Intuition", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You can no longer have disadvantage on attack rolls against creatures within 10 feet of you due to not being able to see them.", "summary": "No disadvantage on attacks against unseen creatures within 10 feet."}, {"name": "Vow of the Limber", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "7th level", "description": "When you make your first unarmed strike on your turn, you can choose to spend 1 focus point. If you do so, your reach with your unarmed strikes increases by 5 feet until the end of your turn.", "summary": "Spend 1 Focus point on your first unarmed strike to extend unarmed reach by 5 ft until end of turn."}, {"name": "Vow of the Nemesis", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "13th level", "description": "As a bonus action, you can choose one creature within 30 feet that you can see. The creature must make a Wisdom saving throw against your focus save DC. On a successful save, the creature becomes immune to this feature for 24 hours. On a failed save, for the next minute, the creature has disadvantage on attack rolls against creatures other than you, and it must make an additional Wisdom saving throw each time it attempts to move to a space that is more than 30 feet away from you; if it succeeds on this saving throw, this feature doesn't restrict its movement for that turn. \n\nThis feature ends early if you attack another creature, if you target another hostile creature with a power or class feature, if a friendly creature damages the target, if a friendly creature targets it with a power or class feature, or if you target another creature with this feature.", "summary": "Bonus action (30 ft, Wisdom save): for 1 minute, target has disadvantage attacking others and must save to move over 30 ft away."}, {"name": "Vow of the Open Mind", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You gain proficiency in a skill of your choice. Additionally, you can spend 1 focus point and 10 minutes meditating on a skill in which you are proficient. If you do so, when you make an ability check with the chosen skill, you can add your Wisdom or Charisma modifier to the check. You can only have one instance of this feature active at a time.", "summary": "Gain one skill proficiency; spend 1 Focus point and 10 minutes to add Wisdom or Charisma modifier to checks with one proficient skill."}, {"name": "Vow of Precision", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "13th level", "description": "Your critical hit range with unarmed strikes increases by 1.", "mechanics": {"unarmedCritBonus": 1}, "summary": "Unarmed strike critical hit range increases by 1."}, {"name": "Vow of Requital", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "13th level", "description": "When you take the Dodge action and an attack made by a creature within 5 feet of you misses you before the start of your next turn, you can use your reaction to make one melee weapon attack with a monk weapon or unarmed strike against that creature.", "summary": "Reaction when an attacker within 5 ft misses you after you Dodge: make one unarmed strike or monk weapon attack."}, {"name": "Vow of Restoration", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "When you would make an unarmed strike, you can spend 1 focus point to instead touch a willing creature within your reach. Roll your Martial Arts die. The target gains hit points equal to the amount rolled + your Wisdom or Charisma modifier (your choice, minimum of +1).", "summary": "Spend 1 Focus point in place of an unarmed strike to heal a willing creature within reach for Martial Arts die + Wisdom/Charisma modifier."}, {"name": "Vow of the Sentry", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You gain proficiency in light and medium armor. Additionally, you can now gain the benefits of your Martial Arts and Unarmored Movement features while wearing light or medium armor as long as you are not wielding a shield.", "mechanics": {"armorProf": ["Light", "Medium"], "monkArmorAllowed": true}, "summary": "Proficiency in light and medium armor; use Martial Arts and Unarmored Movement while wearing them without a shield."}, {"name": "Vow of Serenity", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "Your maximum focus increases by an amount equal to half your Wisdom or Charisma modifier (your choice, minimum of +1).", "mechanics": {"focusMaxHalfForceMod": true}, "summary": "Maximum Focus points increase by half your Wisdom or Charisma modifier (minimum +1)."}, {"name": "Vow of Spirit", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "You can use your choice of Wisdom or Charisma instead of Strength or Dexterity for the attack and damage rolls of your unarmed strikes and monk weapons. You must use the same modifier for both rolls.", "mechanics": {"monkUsesForceMod": true}, "summary": "Use Wisdom or Charisma instead of Strength or Dexterity for unarmed strikes and monk weapons."}, {"name": "Vow of the Versatile", "className": "Monk", "poolName": "Monastic Vows", "prerequisite": "", "description": "When you would make an unarmed strike as part of your Martial Arts bonus action attack or your Flurry of Blows, you can instead make a weapon attack with a monk weapon you are wielding, using your Martial Arts die in place of the weapon's damage.", "summary": "Use a monk weapon with your Martial Arts die in place of unarmed strikes for bonus action attacks and Flurry of Blows."}, {"name": "Commander's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You gain proficiency in medium armor.", "mechanics": {"armorProf": ["Medium"]}, "summary": "Gain proficiency in medium armor."}, {"name": "Explorer's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You can hold your breath twice as long as you are normally able to, and take half as much damage from fall damage.", "mechanics": {"resistances": ["falling"]}, "summary": "Hold breath twice as long and take half damage from falling."}, {"name": "Fate's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "7th level", "description": "When you finish a short or long rest, roll a d20 and record the number rolled. Once before your next short or long rest, you can replace any attack roll, saving throw, or ability check made by you or a creature within 5 feet of you with this roll. You must choose to do so before the roll.", "mechanics": {"shortRestD20Pool": true}, "summary": "After a short or long rest, roll a d20 and save it to replace one attack, save, or check within 5 ft."}, {"name": "Fighter's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You adopt a particular style of fighting as your specialty. Choose one of the fighting Style options, detailed in Chapter 6.", "mechanics": {"grantsFightingStyle": true}, "summary": "Learn one Fighting Style option."}, {"name": "Freedom's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You ignore unenhanced difficult terrain, and when you would use your action to break free of an effect that is grappling or restraining you, you can instead use your bonus action.", "mechanics": {"ignoreDifficultTerrain": true}, "summary": "Ignore unenhanced difficult terrain; escape grapples or restraints as a bonus action."}, {"name": "Guerrilla's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You only need 3 hours of sleep during a long rest to gain its benefits, instead of 6. Additionally, if your long rest would be interrupted, you only need to complete the long rest instead of restarting it to gain its benefits. Lastly, you have advantage on saving throws against exhaustion.", "summary": "Only 3 hours of sleep needed for a long rest, interruptions do not reset rest, and advantage on saves against exhaustion."}, {"name": "Learner's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You gain proficiency in a skill and a tool, or two tools.\n\nYou can select this exploit multiple times, each time choosing a new skill and a tool, or two new tools.", "summary": "Gain proficiency in one skill and one tool, or two tools (repeatable)."}, {"name": "Mentor's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "13th level", "description": "Once per turn, whenever both you and a friendly creature within 60 feet that can see and hear you both have to make a saving throw to resist the same effect, you can choose to have disadvantage on the save. If you do so, the friendly creature gains advantage on the save. You can use this feature before or after you both make the saving throw, but you must do so before the GM says whether the save succeeds or fails.", "summary": "Once per turn when both you and an ally within 60 ft save against the same effect, take disadvantage to grant the ally advantage."}, {"name": "Skill's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You learn an exploit that enhances your ability to apply your knowledge to combat situations. You can take this exploit multiple times.\n\nWhen you take the Attack action, you can use one of your skill exploits granted by this feature. You can use these features a combined two times. You gain an additional use at 5th, 9th, 13th, and 17th level. You regain any expended uses when you finish a long rest.\n\nChoose from the following. You must be proficient in the skill in order to take that skill's exploit. \n\n***Aim (Stealth).*** You attempt to line up a strike against a creature you can see that you are hidden from. Make a Dexterity (Stealth) check contested by the target's Wisdom (Perception) check. If your check succeeds, you gain a +10 bonus to the first attack roll you make against the target before the end of your next turn. If your check fails, you are no longer hidden from the target.\n\n***Angle (Perception).*** You attempt to predict the behavior of a humanoid you can see within 30 feet. Make a Wisdom (Perception) check contested by the target's Dexterity (Sleight of Hand) check. If your check succeeds, the first attack roll the target makes before the start of your next turn has disadvantage, and the first saving throw the creature makes before the start of your next turn has disadvantage. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Battle Cry (Intimidation).*** You attempt to demoralize one humanoid you can see within 30 feet of you that can see and hear you. Make a Charisma (Intimidation) check contested by the target's Wisdom (Insight) check. If your check succeeds, the target is frightened until the end of your next turn. If the target was already frightened of you, it must immediately drop whatever it is holding. On its next turn, if it is still frightened of you, it must take the Dash action and move away from you by the safest available route on its turn, unless there is nowhere to move. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Charm (Persuasion).*** You attempt to convince one humanoid you can see within 30 feet that can hear and understand you. Make a Charisma (Persuasion) check contested by the target's Wisdom (Insight) check. If you have dealt damage to the creature in the last hour, it has advantage on the check. If your check succeeds, the target is charmed by you until the start of your next turn, and it has disadvantage on the first attack roll it makes against a creature before the end of its next turn. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Confuse Beast (Animal Handling).*** You attempt to confuse one beast on the battlefield. Make a Wisdom (Animal Handling) check contested by the target's Wisdom (Insight) check. If your check succeeds, the beast cannot take actions or reactions until the end of your next turn. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Distract (Performance).*** You attempt to distract one beast or humanoid you can see within 30 feet of you that can see and hear you. Make a Charisma (Performance) check contested by the target's Wisdom (Insight) check. If your check succeeds, the next attack roll made against the target before the start of its next turn has advantage. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Emulate Predator (Nature).*** You attempt to emulate the sounds of a natural predator of a beast or plant you can see within 30 feet. Make an Intelligence (Nature) check contested by the target's Wisdom (Insight) check. If your check succeeds, the target must take the Dash action and move away from you by the safest available route on its turn, unless there is nowhere to move. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Feint (Deception).*** You attempt to divert the attention of a target you can see within 30 feet. Make a Charisma (Deception) check contested by the target's Wisdom (Insight) check. If your check succeeds, the first attack roll made against the target before the start of \n\nyour next turn by someone other than you has advantage, and the target has disadvantage on the first saving throw they make against an effect caused by a creature other than you before the start of your next turn. If your check fails, the target can't be deceived by you in this way for 1 hour.\n\n***Hacktivate (Technology).*** You attempt to determine the weaknesses in a droid you can see within 30 feet. Make an Intelligence (Technology) check contested by the target's Intelligence (Technology) check. If your check succeeds, you have advantage on the next attack roll you make against the target before the end of your turn, and if you hit, you deal additional damage equal to your Intelligence modifier. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Instruct (Investigation).*** You attempt to find a weakness in your target. Make an Intelligence (Investigation) check contested by the target's Charisma (Deception) check. If your check succeeds, if a friendly creature makes an attack roll against the target and they can see and hear you, you can use your reaction to grant them advantage on the roll. If you do so, and they hit, they deal additional damage equal to your bonus to Investigation checks. This damage is the same type as the attack's damage. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Intuit (Insight).*** You attempt to determine the motivations of one humanoid you can see within 30 feet. Make a Wisdom (Insight) check contested by the target's Charisma (Deception) check. If your check succeeds, the target can't have advantage on ability checks, attack rolls, or saving throws against you until the end of your next turn. If your check fails, the target instead can't have disadvantage on ability checks, attack rolls, or saving throws against you until the end of your next turn.\n\n***Pocket Sand (Sleight of Hand).*** You attempt to blind one beast or humanoid you can see within 15 feet of you. Make a Dexterity (Sleight of Hand) check contested by the target's Wisdom (Perception) check. If your check succeeds, the target is blinded until the end of your turn. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Precision Strike (Medicine).*** You attempt to strike a pressure point in one humanoid within your reach. Make a Wisdom (Medicine) check contested by the target's Strength (Athletics) or Dexterity (Acrobatics) check (the target chooses the ability to use). If your check succeeds, they are incapacitated until the end of their next turn. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Snare (Survival).*** You attempt to cause a creature within 30 feet of you to stumble. Make a Wisdom (Survival) check contested by the target's Wisdom (Perception) check. If your check succeeds, and the target moves towards you before the start of your next turn, it gains 1 slowed level, and you can use your reaction to cause it to fall prone. If your check fails, you can't use this feature on this target again for 1 hour.\n\n***Spin (Piloting).*** You attempt to confound a piloted construct you can see within 30 feet. Make an \n\nIntelligence (Piloting) check contested by the target's Intelligence (Piloting) check. If your check succeeds, the target has disadvantage on attack rolls against you, and you have advantage on Dexterity saving throws against the target, until the start of your next turn. If your check fails, the target instead has advantage on attack rolls against you, and you have disadvantage on Dexterity saving throws against the target, until the start of your next turn.\n\n***Study (Lore).*** You attempt to anticipate your target's action. Make an Intelligence (Lore) check contested by the target's Charisma (Deception) check. If your check succeeds, you have advantage on the first ability check, attack roll or saving throw you make against that creature before the end of your next turn. Alternatively, before the end of your next turn, you can use your reaction to grant disadvantage on the first ability check, attack roll, or saving throw the target makes against you. If your check fails, you instead have disadvantage on the first ability check, attack roll or saving throw you make against that creature before the end of your next turn.\n\n***Tumble (Acrobatics).*** You attempt to make a quick tumble, immediately moving 10 feet. If you begin or end this movement within a creature's reach, make a Dexterity (Acrobatics) check contested by it's Strength (Athletics) or Dexterity (Acrobatics) check (the target chooses the ability to use). If your check succeeds, this movement does not provoke opportunity attacks from it, and you have advantage on the first attack roll you make against it before the end of your turn. If your check fails, you immediately fall prone.\n\n***Wrestle (Athletics).*** You attempt to grab and pin a creature within 5 feet of you with at least one free hand. The target must be no more than one size larger than you. Make a Strength (Athletics) check contested by the target's Strength (Athletics) or Dexterity (Acrobatics) check (the target chooses the ability to use). If your check succeeds, the target is both grappled and restrained by you. If the target stops being grappled, it also stops being restrained. If your check fails, you can't use this feature on this target again for 1 hour.", "summary": "Learn a combat skill exploit usable with the Attack action (uses scale with level, long rest; repeatable)."}, {"name": "Technologist's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You learn and can cast one 1st-level tech power once per long rest. Your techcasting ability is Intelligence. You require use of a wristpad for this power.\n\nYou can select this exploit multiple times. Each time you do so, you must choose a different power.", "mechanics": {"unlocksTech": true}, "summary": "Learn and cast one 1st-level tech power once per long rest using Intelligence (repeatable)."}, {"name": "Weaponmaster's Exploit", "className": "Operative", "poolName": "Operative Exploits", "prerequisite": "", "description": "You gain proficiency in three blasters or vibroweapons that lack the heavy and strength properties.\n\nYou can select this exploit multiple times. Each time you do so, you must choose different weapons.", "summary": "Gain proficiency in three blasters or vibroweapons lacking the heavy and strength properties (repeatable)."}, {"name": "Academic Memory", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You can recall anything you have read in the past month that you understand. This includes but is not limited to books, maps, signs, and lists.", "summary": "Recall anything you have read and understood in the past month."}, {"name": "Adaptive", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "15th level", "description": "When the target of your Critical Analysis feature is reduced to 0 hit points, you can use your reaction to change the target of your analysis to another creature within range.", "summary": "Reaction when your Critical Analysis target drops to 0 HP: switch Critical Analysis to another creature in range."}, {"name": "Ambassador", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You learn three additional languages of your choice.\n\nYou may choose this discovery multiple times.", "summary": "Learn three additional languages (repeatable)."}, {"name": "Clever Applications", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You gain proficiency with improvised weapons, and they gain the finesse property for you. Additionally, when you make an attack with an improvised weapon, it deals 1d6 damage.\n\nYou can use your Sage Advice feature to give friendly creatures improvised weapon proficiency if they don't already have it, following the same rules of that feature as if it were a skill or tool. The friendly creatures retain this proficiency for the entire duration instead.", "summary": "Proficiency with improvised weapons (1d6 finesse); share improvised weapon proficiency via Sage Advice."}, {"name": "Expert's Advice", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "When you use your Sage Advice feature, the first time each targeted creature makes the chosen skill check, they gain an additional bonus to the roll equal to half your Critical Analysis ability modifier.", "summary": "Sage Advice targets add half your Critical Analysis modifier to their first check with the chosen skill."}, {"name": "Hardened Mind", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "9th level", "description": "You have advantage on saving throws against illusions and on Intelligence checks to discern them from reality.\n\nYou also gain resistance to psychic damage.", "mechanics": {"resistances": ["psychic"], "illusionSaveAdv": true}, "summary": "Advantage on saves and Intelligence checks against illusions; resistance to psychic damage."}, {"name": "Lifelong Learning", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You gain proficiency in a skill and a tool, or two tools.\n\nYou can select this discovery multiple times, each time choosing a new skill and a tool, or two new tools.", "summary": "Gain proficiency in one skill and one tool, or two tools (repeatable)."}, {"name": "Lingering Advice", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "5th level", "description": "When you use your Sage Advice feature, the targeted creatures retain the benefit from your instruction for the full duration.", "summary": "Sage Advice targets retain your instruction benefit for the full 1-hour duration."}, {"name": "Malleable Maneuvering", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You learn two additional maneuvers. When you complete a short rest, you can replace one of these maneuvers with another one. When you complete a long rest, you can replace both of these maneuvers with other ones.", "summary": "Learn two additional maneuvers; swap one on a short rest or both on a long rest."}, {"name": "Master's Advice", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "11th level, Expert's Advice", "description": "When you use your Sage Advice feature, the first time each targeted creature makes the chosen skill check, they gain an additional bonus to the roll equal to your Critical Analysis ability modifier.", "summary": "Sage Advice targets add your full Critical Analysis modifier to their first check with the chosen skill."}, {"name": "Mental Prowess", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "When you make a Strength (Athletics) or Dexterity (Acrobatics) check to grapple a creature or break out of a grapple, net, and other restraining equipment, you can use your Critical Analysis ability modifier instead of Strength or Dexterity.", "summary": "Use your Critical Analysis modifier instead of Strength or Dexterity to grapple or escape grapples and restraints."}, {"name": "Moderately Armored", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "5th level", "description": "You gain proficiency in medium armor.", "mechanics": {"armorProf": ["Medium"]}, "summary": "Gain proficiency in medium armor."}, {"name": "Perfect Maneuver", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "Your superiority die rolls gain a minimum roll threshold, discussed in chapter 7.", "summary": "Your superiority die rolls gain a minimum roll threshold."}, {"name": "Quick Analysis", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "9th level", "description": "When you roll initiative and aren't surprised, you can use your reaction to use your Critical Analysis feature.", "summary": "Reaction when rolling initiative (if not surprised) to activate Critical Analysis."}, {"name": "Rancor's Discipline", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You can substitute Wisdom or Charisma (chosen when you study this discipline) for Intelligence for your scholar class features, except for other discoveries and Academic Pursuit features.", "summary": "Substitute Wisdom or Charisma for Intelligence in base Scholar class features."}, {"name": "Reliable Sources", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "9th level", "description": "Intelligence (Lore) or Intelligence (Nature) skill check that lets you add your proficiency bonus gain a minimum roll threshold, discussed in chapter 7.", "summary": "Proficient Lore and Nature checks gain a minimum roll threshold."}, {"name": "Resolute", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "When you make a saving throw to resist charm and fear effects, you may add your Intelligence modifier to the roll.", "mechanics": {"charmFrightSaveInt": true}, "summary": "Add your Intelligence modifier to saving throws against charm and fear effects."}, {"name": "Running on Fumes", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You only need 3 hours of sleep during a long rest to gain its benefits, instead of 6. Additionally, if your long rest would be interrupted, you only need to complete the long rest instead of restarting it to gain its benefits. Lastly, you have advantage on saving throws against exhaustion.", "summary": "Only 3 hours of sleep needed for a long rest, interruptions do not reset rest, and advantage on saves against exhaustion."}, {"name": "Survival Expert", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "When you make a Survival skill check, you may use your Critical Analysis ability modifier instead of your Wisdom modifier.\n\nAdditionally, you have advantage on saving throws against poison.", "mechanics": {"survivalUsesInt": true}, "summary": "Use your Critical Analysis modifier for Survival checks; advantage on saves against poison."}, {"name": "Targeted Analysis", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "5th level", "description": "Your attack rolls against the target of your Critical Analysis feature cannot suffer from disadvantage.", "summary": "Your attack rolls against your Critical Analysis target cannot suffer from disadvantage."}, {"name": "Tech Amateur", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You learn and can cast one 1st-level tech power once per long rest. Your techcasting ability is Intelligence. You require use of a wristpad for this power.\n\nYou can select this discovery multiple times. Each time you do so, you must choose a different power.", "mechanics": {"unlocksTech": true}, "summary": "Learn and cast one 1st-level tech power once per long rest using Intelligence (repeatable)."}, {"name": "Universal Language", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "You can communicate simple ideas with any creature with an Intelligence score of 6 or higher through basic expressions and gestures.", "summary": "Communicate simple ideas with any creature of Intelligence 6+ via expressions and gestures."}, {"name": "Versatile Maneuvers", "className": "Scholar", "poolName": "Discoveries", "prerequisite": "", "description": "Choose two maneuvers you know. The chosen maneuvers count as general maneuvers for you. You can choose another maneuver at 5th, 9th, 13th, and 17th level. Whenever you gain a level in this class, you can replace one of these maneuvers with another maneuver you know.", "summary": "Treat two known maneuvers (scaling with level) as general maneuvers; swap one on level up."}, {"name": "Adaptability Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "At the start of each of your turns, you can choose an ability score with a saving throw in which you are not proficient. Until the start of your next turn, you add half your proficiency bonus to saving throws you make with the chosen ability. Alternatively, \n\nyou can choose to extend this benefit to allies within 5 feet of you.", "mechanics": {"routineEffect": "Adaptability Routine"}, "summary": "Start of turn: add half proficiency bonus to one non-proficient saving throw (self or allies within 5 ft)."}, {"name": "Maven's Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "At the start of each of your turns, you can choose to gain resistance to damage from tech powers until the start of your next turn. Alternatively, you can choose to extend this benefit to allies within 5 feet of you.", "mechanics": {"routineEffect": "Maven's Routine"}, "summary": "Start of turn: gain resistance to damage from tech powers (self or allies within 5 ft)."}, {"name": "Mesmer's Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "At the start of each of your turns, you can choose to have advantage on saving throws against effects that would incapacitate you or put you to sleep until the start of your next turn. Alternatively, you can choose to extend this benefit to allies within 5 feet of you.", "mechanics": {"routineEffect": "Mesmer's Routine"}, "summary": "Start of turn: advantage on saves against incapacitation and sleep (self or allies within 5 ft)."}, {"name": "Nomad's Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "At the start of each of your turns, you can choose to gain advantage on Constitution saving throws to avoid exhaustion from unenhanced sources, as well as being naturally adapted to both hot and cold climates. Alternatively, you can choose to extend this benefit to allies within 5 feet of you.", "mechanics": {"routineEffect": "Nomad's Routine"}, "summary": "Start of turn: advantage on Constitution saves against unenhanced exhaustion and adapted to hot/cold climates (self or allies within 5 ft)."}, {"name": "Responder's Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "When you roll initiative, you can choose to add your proficiency bonus to the initiative check and have advantage on attack rolls against creatures that have not yet acted. Alternatively, you can choose to allow each friendly creature within 5 feet of you to add half your proficiency bonus to the initiative check and have advantage on the first attack roll they make against a creature that has not yet acted.", "mechanics": {"initiativeProf": true}, "summary": "Add proficiency bonus to initiative and gain advantage on attacks against creatures that have not acted yet (half/first attack for allies within 5 ft)."}, {"name": "Sharpshooter's Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "At the start of each of your turns, you can choose to gain a bonus to the first weapon attack roll you make before the start of your next turn equal to your Intelligence modifier. Alternatively, you can choose to allow each friendly creature within 5 feet of you to add half your Intelligence modifier to the first weapon attack roll they make before the start of your next turn.", "mechanics": {"routineEffect": "Sharpshooter's Routine"}, "summary": "Start of turn: add Intelligence modifier (half for allies within 5 ft) to the first weapon attack roll before your next turn."}, {"name": "Strider's Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "At the start of each of your turns, you can choose to have each slowed level only reduce your speed by 5 feet, unless it would reduce your speed to 0 until the start of your next turn. Alternatively, you can choose to extend this benefit to allies within 5 feet of you.", "mechanics": {"slowedStep": 5}, "summary": "Start of turn: slowed levels reduce speed by only 5 ft instead of 10 ft (self or allies within 5 ft)."}, {"name": "Warden's Routine", "className": "Scout", "poolName": "Scout Routines", "prerequisite": "", "description": "At the start of each of your turns, you can choose to gain a crawling, climbing, and swimming speed equal to your walking speed until the start of your next turn. Alternatively, you can choose to extend this benefit to allies within 5 feet of you.", "mechanics": {"climbSpeed": "walk", "swimSpeed": "walk"}, "summary": "Start of turn: gain crawling, climbing, and swimming speeds equal to walking speed (self or allies within 5 ft)."}, {"name": "Ideal of the Agile", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "You gain a swimming speed and a climbing speed equal to your walking speed. When you make a long jump, you can cover a number of feet up to twice your Wisdom or Charisma score (your choice). When you make a high jump, you can leap a number of feet up into the air equal to 3 + twice your Wisdom or Charisma modifier (your choice).\n\nAdditionally, as a bonus action, you can manifest this ideal in a brief surge of energy. For the next minute, opportunity attacks against you are made with disadvantage.", "mechanics": {"climbSpeed": "walk", "swimSpeed": "walk"}, "summary": "Climbing & swimming speed equal to walk speed; Wisdom/Charisma jumps; manifest (bonus action, 1 minute) so opportunity attacks against you have disadvantage."}, {"name": "Ideal of the Artisan", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "Choose one of your skill or tool proficiencies. When you make an ability check with the chosen skill or tool, you can add half your Wisdom or Charisma modifier (your choice, minimum of one).\n\nAdditionally, as an action, you can manifest this ideal in a brief surge of energy. For the next 10 minutes, the bonus increases to your Wisdom or Charisma modifier, and you can choose a second skill or tool to extend this feature to.", "summary": "Add half Wisdom/Charisma modifier to one skill/tool; manifest (action, 10 minutes) for full modifier on two skills/tools."}, {"name": "Ideal of the Contender", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "Your unarmed strike damage increases by one step (from 1 to d4, d4 to d6, or d6 to d8), and your unarmed strikes gain the finesse property.\n\nAdditionally, as a bonus action, you can manifest this ideal in a brief surge of energy. For the next minute, your unarmed strikes count as enhanced for the purpose of overcoming resistance and immunity to unenhanced attacks and damage, and you can use your Wisdom or Charisma modifier (your choice) instead of Strength for checks made to grapple a target or escape a grapple.", "mechanics": {"unarmedDieStep": 1, "unarmedFinesse": true}, "summary": "Unarmed strike die steps up by one and gains finesse; manifest (bonus action, 1 minute) for enhanced unarmed strikes and Wisdom/Charisma grapples."}, {"name": "Ideal of the Fighter", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "You adopt a particular style of fighting as your specialty. Choose one of the fighting style options, detailed in Chapter 6. \n\nAdditionally, as a bonus action, you can manifest this ideal in a brief surge of energy. For the next minute, you know the fighting mastery that corresponds with the fighting style you chose with this feature. If you already know that fighting mastery, you instead learn another of your choice for the duration.", "mechanics": {"grantsFightingStyle": true}, "summary": "Learn one Fighting Style; manifest (bonus action, 1 minute) to gain its corresponding Fighting Mastery."}, {"name": "Ideal of the Hunter", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "You gain darkvision out to a range of 60 feet. If you already have darkvision, this ideal increases its range by 30 feet.\n\nAdditionally, as a bonus action, you can manifest this ideal in a brief surge of energy. For the next minute, you can see normally in enhanced darkness, and you gain blindsight to 10 feet.", "mechanics": {"darkvision": 60, "darkvisionExtend": 30}, "summary": "Darkvision 60 ft (or +30 ft); manifest (bonus action, 1 minute) to see in enhanced darkness and gain 10 ft blindsight."}, {"name": "Ideal of the Steadfast", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "When you would make a melee weapon attack roll, you can instead force the target to make a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon). If you would have advantage on your attack roll, the creature instead has disadvantage on their saving throw, and if you would have disadvantage on your attack roll, the creature instead has advantage on their saving throw. On a failed save, the target takes normal weapon damage and is subjected to any additional effects that would occur on a hit.\n\nAdditionally, as a bonus action, you can manifest this ideal in a brief surge of energy. For the next minute, when a creature succeeds on the saving throw, they take half the normal weapon damage, and when a creature rolls a 1 on the saving throw, they treat the damage as if you had rolled the maximum.", "summary": "Replace melee weapon attack roll with a Dexterity save; manifest (bonus action, 1 minute) for half damage on save and maximum damage on natural 1."}, {"name": "Ideal of the Titan", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "You gain proficiency in medium armor.\n\nAdditionally, as a bonus action, you can manifest this ideal in a brief surge of energy. For the next minute, you have advantage on ability checks and attack rolls that would forcefully move another creature, and the distance they would be moved increases by 5 feet.", "mechanics": {"armorProf": ["Medium"]}, "summary": "Proficiency in medium armor; manifest (bonus action, 1 minute) for advantage and +5 ft distance on forced movement."}, {"name": "Ideal of the Tranquil", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "When you finish a short or long rest, you gain a number of temporary force points equal to half your Wisdom or Charisma modifier (your choice, minimum of one). When you would spend a force point while you have temporary force points, the temporary force points are spent first. All temporary force points are lost at the end of your next short or long rest.\n\nAdditionally, as an action, you can manifest this ideal in a brief surge of energy. You regain a number of force points equal to half your Wisdom or Charisma modifier (your choice, minimum of one).", "mechanics": {"restTempForceHalfMod": true}, "summary": "Gain temporary Force points (half Wisdom/Charisma modifier) on short/long rest; manifest (action) to regain that many Force points."}, {"name": "Ideal of the Vigorous", "className": "Sentinel", "poolName": "Sentinel Ideals", "prerequisite": "", "description": "When you roll a Hit Die to regain hit points, you may use your Wisdom or Charisma modifier in place of your Constitution modifier when determining the number of hit points you regain.\n\nAdditionally, as an action, you can manifest this ideal in a brief surge of energy. You gain a number of temporary hit points equal to half your sentinel level + your Wisdom or Charisma modifier (your choice, minimum of one).", "mechanics": {"hitDieUsesForceMod": true}, "summary": "Use Wisdom/Charisma modifier instead of Constitution for Hit Die healing; manifest (action) for temporary HP equal to half Sentinel level + Wisdom/Charisma modifier."}];
const SW5E_CLASS_IMPROVEMENTS = [{"className": "Berserker", "label": "Instinctive Pounce / Pursuit", "description": "When a creature ends its turn within 15 feet of you, you can use your reaction to move up to half your speed to a space closer to the creature. This movement doesn't provoke opportunity attacks.", "mechanics": {"label": "Instinctive Pounce / Pursuit", "timing": "reaction", "summary": "Reaction when foe ends turn within 15 ft: move up to half speed toward them"}}, {"className": "Consular", "label": "Force Versatility", "description": "When you complete a long rest, you can choose one of the force powers you know and replace it with another force power, as long as that power is not of a higher level than your Max Power Level.", "mechanics": {"label": "Force Versatility", "timing": "passive", "summary": "Swap one known force power on long rest"}}, {"className": "Engineer", "label": "Potent Power Aptitude", "description": "When a creature has a Potent Aptitude die from you and casts a power, they can roll the die and add the number rolled to one damage or healing roll of the power. If the power would damage or heal multiple targets, this bonus only applies to one of them. The Potent Aptitude die is then lost.", "mechanics": {"label": "Potent Power Aptitude", "timing": "passive", "summary": "Allies with Potent Aptitude die can add it to a power damage/healing roll"}}, {"className": "Fighter", "label": "Martial Versatility", "description": "Whenever you complete a long rest, you can replace a fighting style you know with another style available. You can't take a Fighting Style option more than once, even if you later get to choose again.", "mechanics": {"label": "Martial Versatility", "timing": "passive", "summary": "Swap a known fighting style on long rest"}}, {"className": "Guardian", "label": "Harness the Force", "description": "As a bonus action, you can expend a use of your Channel the Force to regain 2 force points. You can use this feature a number of times equal to your proficiency bonus, as shown in the guardian table. You regain all expended uses when you complete a long rest.", "mechanics": {"label": "Harness the Force", "timing": "bonus", "harnessForce": true, "summary": "Bonus action: spend 1 Channel the Force to regain 2 Force Points (proficiency bonus uses per long rest)"}}, {"className": "Monk", "label": "Quickened Healing", "description": "As an action, you can spend 2 focus points and a roll a Martial Arts die. You regain a number of hit points equal to the amount rolled + your Wisdom or Charisma modifier (your choice, a minimum of one).", "mechanics": {"label": "Quickened Healing", "timing": "action", "quickenedHealing": true, "summary": "Action: spend 2 Focus Points to regain Martial Arts die + proficiency HP"}}, {"className": "Operative", "label": "Steady Aim", "description": "You can use the bonus action granted by your Cunning Action to carefully aim your next attack. You gain advantage on your next attack roll before the end of your current turn. You can't use this feature if you have moved during this turn, and using this feature reduces your speed to 0 until the end of your current turn.", "mechanics": {"label": "Steady Aim", "timing": "bonus", "steadyAim": true, "summary": "Cunning Action bonus: advantage on next attack this turn (speed 0 this turn)"}}, {"className": "Scholar", "label": "Maneuver Versatility", "description": "When you complete a long rest, you can choose one of the maneuvers you know and replace it with another one.", "mechanics": {"label": "Maneuver Versatility", "timing": "passive", "summary": "Swap one known maneuver on long rest"}}, {"className": "Scout", "label": "Tireless", "description": "As an action, you can reduce your exhaustion level by 1 and give yourself a number of temporary hit points equal to 1d10 + your scout level. \n\nOnce you've used this feature, you must complete a short or long rest before you can use it again.", "mechanics": {"label": "Tireless", "timing": "action", "tireless": true, "summary": "Action: reduce exhaustion by 1 and gain 1d10 + techcasting modifier temporary HP"}}, {"className": "Sentinel", "label": "Empowered Kinetic Combat", "description": "Once per turn, when you roll a Kinetic Combat die, you can roll the die with advantage.", "mechanics": {"label": "Empowered Kinetic Combat", "timing": "free", "summary": "once per turn roll a Kinetic Combat die with advantage"}}];
